       transition: transform 0.15s ease, background 0.15s ease, opacity 0.15s ease;
       box-shadow: 0 10px 24px rgba(37, 99, 235, 0.22);
     }

     button:hover {
       background: var(--accent-hover);
       transform: translateY(-1px);
     }

     button:focus-visible,
     input[type="checkbox"]:focus-visible {
       outline: 3px solid var(--focus);
       outline-offset: 2px;
     }

     button:disabled {
       cursor: not-allowed;
       opacity: 0.55;
       transform: none;
       box-shadow: none;
     }
   </style>
 </head>
 <body>
   <main class="card">
     <h1>Terms of Use</h1>
     <p>Please confirm your agreement before continuing.</p>

     <form id="consent-form">
       <div class="form-field">
         <input type="checkbox" id="terms" name="terms" required />
         <div class="checkbox-copy">
           <label for="terms">I agree to the Terms of Use</label>
           <span class="helper-text">You must accept the terms to submit this form.</span>
         </div>
       </div>

       <div class="actions">
         <button type="submit" id="submit-button">Submit</button>
       </div>
     </form>
   </main>

   <script>
     const form = document.getElementById('consent-form');
     const checkbox = document.getElementById('terms');
     const button = document.getElementById('submit-button');

     const syncButtonState = () => {
       button.disabled = !checkbox.checked;
     };

     checkbox.addEventListener('change', syncButtonState);

     form.addEventListener('submit', (event) => {
       event.preventDefault();
       if (!form.checkValidity()) {
         form.reportValidity();
         return;
       }
       button.textContent = 'Submitted';
       button.disabled = true;
     });

     syncButtonState();
   </script>
 </body>
 </html>

